const faqs=[
['navle','Har jeg riktig anatomi for navlepiercing?','En navle må vurderes både stående, sittende og i bevegelse. Det trengs en tydelig hudfold som kan støtte smykket uten konstant trykk. Et bilde kan gi en foreløpig vurdering, men erstatter ikke en fysisk konsultasjon.'],
['navle','Er navlepiercingen min plassert riktig?','En klassisk navlepiercing skal gå gjennom vevsfolden over navlen — ikke bare gjennom flat magehud. Vinkel, dybde, synlig stav og trykk fra smykket må vurderes samlet.'],
['navle','Hvorfor ser det ut som jeg har en “surface piercing” i stedet?','Hvis den nederste delen av smykket ikke kommer ut inne i navlen, eller bare et tynt hudlag holder smykket, kan plasseringen være for overfladisk. Få den vurdert av en erfaren piercer.'],
['navle','Hva er en floating navel, og passer det bedre for meg?','En floating navel bruker vanligvis en flat ende nederst og kan passe når navlen komprimeres eller lukkes når du sitter. Valget krever fysisk vurdering av anatomi og bevegelse.'],
['navle','Hvordan ser migrasjon eller avstøtning i navlen ut?','Tegn kan være at huden mellom hullene blir tynnere, mer av staven blir synlig, hullene flytter seg eller huden blir blank og rød. Endringer over tid er viktigere enn ett bilde.'],
['tilheling','Er hevelse og rødhet normalt etter en ny piercing?','Lokal hevelse, ømhet og lett rødhet kan være normalt tidlig. Det bør gradvis roe seg. Rask forverring, sterk varme, intens smerte eller feber krever rask faglig vurdering.'],
['tilheling','Er gul eller hvit væske et tegn på infeksjon?','Lys sårvæske som tørker til skorpe kan være en del av tilhelingen. Tykk illeluktende væske sammen med økende smerte, varme, rødhet eller sykdomsfølelse bør vurderes av lege.'],
['tilheling','Hvorfor har jeg fått en kul ved piercingen?','Kuler skyldes ofte irritasjon fra trykk, bevegelse, feil størrelse, vinkel eller traume. Ikke press, stikk hull på eller behandle kulen med sterke hjemmemidler. Finn årsaken sammen med en piercer.'],
['tilheling','Er dette irritasjon, infeksjon eller allergi?','De kan ligne hverandre og kan ikke skilles sikkert med en enkel nettbeskrivelse. Historikk, materiale, plassering, symptomer og utvikling må vurderes samlet.'],
['tilheling','Hvor lenge tar det før en piercing gror?','Det varierer mye etter plassering, helse, smykke og belastning. At utsiden ser rolig ut betyr ikke nødvendigvis at kanalen er ferdig tilhelet.'],
['tilheling','Hvorfor gror ikke piercingen min?','Vanlige årsaker er konstant trykk, å sove på den, feil smykke, for mye rengjøring, gjentatte støt, fukt eller uegnet plassering. Start med å finne den mekaniske årsaken.'],
['tilheling','Kan jeg ta ut smykket når området er betent?','Ikke ta det ut på egen hånd ved mistanke om infeksjon. Kanalen kan lukke seg og gjøre situasjonen vanskeligere. Kontakt lege og en erfaren piercer for riktig neste steg.'],
['smykke','Når trenger jeg downsizing?','Når den første hevelsen har lagt seg, kan en for lang stav bevege seg og hekte seg fast. Tidspunktet varierer med piercingtype og tilheling, og bør vurderes før bytte.'],
['smykke','Er staven min for lang eller for kort?','En for kort stav kan presse og synke inn; en for lang stav kan bevege seg, vri seg og irritere. Passform vurderes best når hevelsen og plasseringen er kjent.'],
['smykke','Hvilket materiale er tryggest i en ny piercing?','Implantatklassifisert titan er et vanlig førstevalg. Det viktige er dokumentert kvalitet, god overflate og riktig design — ikke bare at produktet kalles “kirurgisk stål”.'],
['smykke','Kan jeg bytte smykke selv?','Et tidlig bytte kan skade kanalen eller introdusere bakterier. Første downsizing eller problemløsende bytte bør vanligvis gjøres av en piercer.'],
['smykke','Hvorfor synker kulen eller platen inn i huden?','Det kan skyldes hevelse eller for kort smykke og bør vurderes raskt. Hvis smykket holder på å bli omsluttet av hud, få hjelp samme dag.'],
['hverdag','Kan jeg sove på en ny piercing?','Direkte trykk kan endre vinkel og forlenge irritasjon. Unngå å sove på området og bruk støtte som holder trykket borte.'],
['hverdag','Kan jeg bade i basseng, sjø eller boblebad?','Nye piercinger bør beskyttes mot unødvendig bakterieeksponering. Vent til den tidlige sårfasen er over og følg råd tilpasset plasseringen.'],
['hverdag','Kan jeg trene etter piercing?','Rolig aktivitet går ofte fint hvis piercingen ikke får trykk, friksjon eller slag. Rengjør ikke overdrevent etter trening; dusj og tørk forsiktig.'],
['hverdag','Hvordan skal jeg rengjøre piercingen?','Vask hendene, skyll skånsomt og la området være mest mulig i fred. Unngå alkohol, hydrogenperoksid, tea tree oil og å rotere smykket.'],
['hverdag','Kan klær irritere navlepiercingen?','Ja. Linninger, belter og tettsittende treningstøy kan gi gjentatt trykk og bevegelse. Velg klær som ikke presser på smykket.'],
['hverdag','Kan jeg bruke plaster over piercingen?','Tett tildekking kan holde på fukt og gi friksjon. Kortvarig beskyttelse kan noen ganger brukes ved risiko for støt, men bør ikke bli en fast løsning.'],
['hjelp','Når bør jeg kontakte piercer?','Ved vedvarende irritasjon, endret vinkel, mulig migrasjon, feil passform, usikker anatomi eller behov for downsizing. Ta med dato, smykkedata og bilder over tid.'],
['hjelp','Når bør jeg kontakte lege?','Ved feber, raskt økende smerte eller hevelse, tydelig varme, røde striper, sykdomsfølelse eller andre alvorlige symptomer. Akutte symptomer skal ikke vente på en nettvurdering.'],
['hjelp','Kan en piercing vurderes sikkert bare fra ett bilde?','Et bilde kan avdekke enkelte synlige forhold, men ikke vevskvalitet, temperatur, smerte eller hvordan anatomien endrer seg i bevegelse. Bruk foto som del av en strukturert vurdering.'],
['hjelp','Hva bør være med i bilder til en nettvurdering?','Ta ett oversiktsbilde og ett nærbilde i godt dagslys, uten filter. Vis området avslappet og unngå ansikt eller andre identifiserende detaljer.'],
['hjelp','Kan jeg få en second opinion etter piercing hos en annen?','Ja. En uavhengig piercer kan vurdere plassering, smykke og tilhelingsforløp og forklare hvilke neste steg som er realistiske.']
];
const labels={navle:'Navle',tilheling:'Tilheling',smykke:'Smykke',hverdag:'Hverdag',hjelp:'Hjelp'};
const recs={navle:'Start med spørsmålene om anatomi og plassering. For et sikkert svar må navlen også vurderes i bevegelse.',healing:'Se tilhelingsspørsmålene og sammenlign utviklingen over tid — ikke bare hvordan den ser ut i dag.',downsize:'Se spørsmålene om smykkelengde. Downsizing bør baseres på hevelse, bevegelse og piercingtype.',jewelry:'Start med materiale og passform. Dokumentert kvalitet og riktig størrelse er viktigere enn markedsnavnet.'};
let active='all';
const list=document.querySelector('#faqList'),search=document.querySelector('#searchInput');
function render(){const q=search.value.trim().toLowerCase();const visible=faqs.filter(([tag,title,text])=>(active==='all'||tag===active)&&(`${title} ${text}`.toLowerCase().includes(q)));list.innerHTML=visible.map(([tag,title,text],i)=>`<article class="faq-item"><button class="faq-question" aria-expanded="false"><span class="tag">${labels[tag]}</span><strong>${title}</strong><span class="plus">+</span></button><div class="faq-answer"><p>${text}</p></div></article>`).join('');document.querySelector('#emptyState').hidden=visible.length>0;list.querySelectorAll('.faq-question').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.faq-item');item.classList.toggle('open');btn.setAttribute('aria-expanded',item.classList.contains('open'))}))}render();
search.addEventListener('input',render);document.querySelectorAll('.chip').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('.chip.active').classList.remove('active');btn.classList.add('active');active=btn.dataset.filter;render()}));
const recommendation=document.querySelector('#recommendation');function choosePath(btn){document.querySelector('.path-card.active')?.classList.remove('active');btn.classList.add('active');recommendation.innerHTML=`<span>${recs[btn.dataset.path]}</span><a href="#questions">Vis relevante spørsmål</a>`;const map={navle:'navle',healing:'tilheling',downsize:'smykke',jewelry:'smykke'};active=map[btn.dataset.path];document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c.dataset.filter===active));render()}document.querySelectorAll('.path-card').forEach(btn=>btn.addEventListener('click',()=>choosePath(btn)));choosePath(document.querySelector('.path-card.active'));
const photo=document.querySelector('#photo');photo.addEventListener('change',()=>document.querySelector('#fileName').textContent=photo.files[0]?.name||'Ingen fil valgt');
const modal=document.querySelector('#summaryModal');document.querySelector('#checkForm').addEventListener('submit',e=>{e.preventDefault();const symptoms=[...document.querySelectorAll('[name=symptom]:checked')].map(x=>x.value).join(', ')||'Ikke oppgitt';const txt=`Tema: ${document.querySelector('#topic').value}\nDato for piercing: ${document.querySelector('#date').value||'Ikke oppgitt'}\nSymptomer/observasjoner: ${symptoms}\nBeskrivelse: ${document.querySelector('#description').value||'Ikke oppgitt'}\nBilde valgt: ${photo.files[0]?'Ja — må sendes separat':'Nei'}\n\nJeg ønsker en profesjonell vurdering av plassering, smykke og anbefalt neste steg.`;document.querySelector('#summaryText').textContent=txt;modal.hidden=false});document.querySelector('#closeModal').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',e=>{if(e.target===modal)modal.hidden=true});document.querySelector('#copySummary').addEventListener('click',async e=>{await navigator.clipboard.writeText(document.querySelector('#summaryText').textContent);e.target.textContent='Kopiert';setTimeout(()=>e.target.textContent='Kopier oppsummeringen',1500)});
